import { BrandMark } from "@/components/brand-mark";
import { cn } from "@/lib/utils";

/**
 * The logo of Lumen: the badge with the tape "L" cut out of it.
 * -------------------------------------------------------------------------
 * It is the same mark everywhere: the public site, the login and the
 * panel of every role. The drawing is the one of
 * `assets/brand/logo-lumen.svg`, and the component that carries it is
 * generated by `tools/build_brand.py`, so the app and the exported
 * files can never drift apart.
 *
 * The badge carries its own colours, so it does not inherit the colour
 * of the text around it: on the dark rail of the panel it stays the
 * same green.
 */
export function BrandLogo({ className = "" }: { className?: string }) {
  return <BrandMark className={cn("size-[32px] shrink-0", className)} />;
}
